import './navigation-sidebar.css';

type Row = { label: string; icon?: string; disabled?: boolean; selected?: boolean };
const sections: { title: string; rows: Row[] }[] = [{ title: 'Workspace', rows: [{ label: 'Overview', icon: '⌂', selected: true }, { label: 'Activity', icon: '◷' }, { label: 'Reports', disabled: true }] }, { title: 'Manage', rows: [{ label: 'Members', icon: '◉' }, { label: 'Settings' }] }];
export function NavigationSidebar() { return <aside className="nav-sidebar" aria-label="Primary navigation">
  <div className="nav-scroll">{sections.map(section => <section key={section.title}><h2>{section.title}</h2>{section.rows.map(row => <button key={row.label} disabled={row.disabled} aria-current={row.selected ? 'page' : undefined} className={row.selected ? 'selected' : ''}>{row.icon ? <span className="nav-icon" aria-hidden="true">{row.icon}</span> : <span className="nav-icon" />}{row.label}</button>)}</section>)}
  <section className="workspace-summary" aria-label="Current workspace"><strong>Northstar</strong><span>12 active projects</span></section></div>
  <footer><button aria-label="Help">?</button><button aria-label="Account menu">Account</button></footer>
</aside>; }
